def solve():
    N=5
    moves=[(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]
    fixed={0:0,3:23,4:16,5:5,15:15,22:24}
    x=[-1]*25
    used=[False]*25
    for k,v in fixed.items():
        x[k]=v
        used[v]=True

    def neighbors(c):
        r,col=c//5,c%5
        res=[]
        for dr,dc in moves:
            nr,nc=r+dr,col+dc
            if 0<=nr<5 and 0<=nc<5:
                res.append(nr*5+nc)
        return res

    def bt(step):
        if step==25:
            return True
        if x[step]!=-1:
            # check move validity from prev
            if step>0 and x[step-1]!=-1:
                if x[step] not in neighbors(x[step-1]):
                    return False
            return bt(step+1)
        prev=x[step-1]
        for nb in neighbors(prev):
            if not used[nb]:
                # check if nb conflicts with fixed at step
                x[step]=nb
                used[nb]=True
                if bt(step+1):
                    return True
                used[nb]=False
                x[step]=-1
        return False

    if bt(1):
        return x
    return None

print(solve())
